function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  'use strict';
  var SX = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  var TNAMES = ['bolt','cannon','frost','lance','flak'];
  var TT = {
    bolt:   {cost:50,  dmg:26,  per:8,  rng:300, spl:0,  slow:0,  pierce:0, g:1, a:1},
    cannon: {cost:90,  dmg:60,  per:24, rng:260, spl:90, slow:0,  pierce:0, g:1, a:0},
    frost:  {cost:70,  dmg:10,  per:12, rng:240, spl:0,  slow:30, pierce:0, g:1, a:1},
    lance:  {cost:120, dmg:180, per:36, rng:360, spl:0,  slow:0,  pierce:1, g:1, a:0},
    flak:   {cost:80,  dmg:40,  per:10, rng:320, spl:70, slow:0,  pierce:0, g:0, a:1}
  };
  var ENAMES = ['grunt','runner','wisp','brute','splitter','mender','splitling'];
  var ET = {
    grunt:{hp:60,sp:10,bounty:4,leak:1,route:0,first:1,wt:10},
    runner:{hp:40,sp:20,bounty:4,leak:1,route:0,first:2,wt:4},
    wisp:{hp:50,sp:12,bounty:6,leak:2,route:1,first:3,wt:3},
    brute:{hp:150,sp:6,bounty:9,leak:3,route:0,first:4,wt:3},
    splitter:{hp:90,sp:8,bounty:6,leak:2,route:0,first:6,wt:2},
    mender:{hp:70,sp:8,bounty:7,leak:2,route:0,first:8,wt:1},
    splitling:{hp:0,sp:12,bounty:1,leak:1,route:0,first:99,wt:0}
  };
  var GEN = ['grunt','runner','wisp','brute','splitter','mender'];
  function mkRoute(pts) {
    var P = pts.map(function (p) { return [p[0] * 100 + 50, p[1] * 100 + 50]; });
    var cum = [0];
    for (var i = 1; i < P.length; i++) cum.push(cum[i - 1] + Math.abs(P[i][0] - P[i - 1][0]) + Math.abs(P[i][1] - P[i - 1][1]));
    return { P: P, cum: cum, len: cum[cum.length - 1] };
  }
  var ROUTES = [mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]),
                mkRoute([[0,6],[21,6],[21,11],[23,11]])];
  function setPos(e) {
    var R = ROUTES[e.route], p = e.prog;
    if (p > R.len) p = R.len;
    for (var i = 1; i < R.P.length; i++) {
      if (p <= R.cum[i] || i === R.P.length - 1) {
        var a = R.P[i - 1], b = R.P[i], d = p - R.cum[i - 1];
        var sx = Math.sign(b[0] - a[0]), sy = Math.sign(b[1] - a[1]);
        e.x = a[0] + sx * d; e.y = a[1] + sy * d;
        e.dir = Math.atan2(sx, sy);
        return;
      }
    }
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var M = [0, 1000];
  function mw(w) { while (M.length <= w) M.push(Math.floor(M[M.length - 1] * 108 / 100)); return M[w]; }
  function armour(type, w) { return type === 'grunt' ? Math.floor(w / 4) : type === 'brute' ? 6 + w : 0; }

  var rnd = mulberry32(seed);
  var waves = {};
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), types = [], sum = 0, i, k;
    for (i = 0; i < GEN.length; i++) if (ET[GEN[i]].first <= w) { types.push(GEN[i]); sum += ET[GEN[i]].wt; }
    var comp = [];
    for (i = 0; i < n; i++) {
      var r = rnd() % sum;
      for (k = 0; k < types.length; k++) { var wt = ET[types[k]].wt; if (r < wt) break; r -= wt; }
      comp.push(types[k]);
    }
    waves[w] = comp;
  }
  var strat = createStrategy();
  var gold = 250, base = 10, nextId = 1, enemies = [], log = [];
  var turrets = []; for (var si = 0; si < 16; si++) turrets.push(null);
  var spawnQ = {};
  genWave(1);
  var fallTick = -1, curWave = 0, ev = null;
  if (rec) { rec.frames = []; rec.waveStart = {}; }

  function newEnemy(type, w, hp, prog) {
    var d = ET[type];
    var e = { id: nextId++, type: type, w: w, hp: hp, mhp: hp, prog: prog, age: 0, slow: 0, route: d.route,
      air: d.route, arm: armour(type, w), sp: d.sp, x: 0, y: 0, dir: 0 };
    setPos(e); return e;
  }
  function view(e) {
    var R = ROUTES[e.route];
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.mhp, x: e.x, y: e.y, air: e.air, armor: e.arm,
      speed: e.slow > 0 ? Math.floor(e.sp * 60 / 100) : e.sp, slowed: e.slow > 0 ? 1 : 0, remaining: R.len - e.prog };
  }
  function tstats(T) {
    var d = TT[T.type].dmg, i; for (i = 1; i < T.tier; i++) d = Math.floor(d * 16 / 10);
    T.dmg = d; T.rng = TT[T.type].rng + 30 * (T.tier - 1);
  }
  function applyActions(acts, t) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a) continue;
      var s = a.slot;
      if (!(Number.isInteger(s) && s >= 0 && s < 16)) continue;
      if (a.op === 'build') {
        var d = TT[a.type];
        if (!d || !Object.prototype.hasOwnProperty.call(TT, a.type) || turrets[s] || gold < d.cost) continue;
        gold -= d.cost;
        var T = { type: a.type, tier: 1, spent: d.cost, cd: 0, dmg: 0, rng: 0 }; tstats(T); turrets[s] = T;
        log.push([t, 'B', s, TNAMES.indexOf(a.type)]);
        if (ev) ev.acts.push([s, 'B']);
      } else if (a.op === 'upgrade') {
        var T2 = turrets[s]; if (!T2 || T2.tier >= 3) continue;
        var c = TT[T2.type].cost * (T2.tier === 1 ? 1 : 2);
        if (gold < c) continue;
        gold -= c; T2.spent += c; T2.tier++; tstats(T2);
        log.push([t, 'U', s, T2.tier]);
        if (ev) ev.acts.push([s, 'U']);
      } else if (a.op === 'sell') {
        var T3 = turrets[s]; if (!T3) continue;
        gold += Math.floor(T3.spent * 70 / 100); turrets[s] = null;
        log.push([t, 'S', s, 0]);
        if (ev) ev.acts.push([s, 'S']);
      }
    }
  }
  function removeDead(t, slot) {
    var any = false, i;
    for (i = 0; i < enemies.length; i++) if (enemies[i].hp <= 0) { any = true; break; }
    if (!any) return;
    var alive = [], born = [];
    for (i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      if (e.hp > 0) { alive.push(e); continue; }
      gold += ET[e.type].bounty;
      log.push([t, 'K', e.id, slot]);
      if (ev) ev.kills.push([e.id, ENAMES.indexOf(e.type), e.x, e.y, e.air]);
      if (e.type === 'splitter') {
        for (var k = 0; k < 3; k++) born.push(newEnemy('splitling', e.w, Math.max(1, Math.floor(e.mhp / 4)), e.prog));
      }
    }
    enemies = alive.concat(born);
  }

  for (var t = 0; t < maxTicks; t++) {
    ev = rec ? { shots: [], kills: [], leaks: [], heals: [], acts: [] } : null;
    var frameExtra = null;
    if (t >= 20 && (t - 20) % 40 === 0) {
      var w = (t - 20) / 40 + 1; curWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      genWave(w + 1);
      var st = { tick: t, wave: w, gold: gold, baseHp: base,
        slots: SX.map(function (p, i) { var T = turrets[i]; return { slot: i, x: p[0], y: p[1], turret: T ? { type: T.type, tier: T.tier, spent: T.spent } : null }; }),
        enemies: enemies.map(view), nextWave: waves[w + 1].slice() };
      applyActions(strat.plan(st), t);
      var comp = waves[w];
      for (var i = 0; i < comp.length; i++) { var tk = t + 4 * i; (spawnQ[tk] = spawnQ[tk] || []).push([comp[i], w]); }
      if (rec) frameExtra = { wave: w, next: waves[w + 1].slice() };
    }
    var sq = spawnQ[t];
    if (sq) { for (var q = 0; q < sq.length; q++) { var ty = sq[q][0], ww = sq[q][1];
      enemies.push(newEnemy(ty, ww, Math.floor(ET[ty].hp * mw(ww) / 1000), 0)); } delete spawnQ[t]; }
    // move
    var fell = false;
    var keep = [];
    for (var m = 0; m < enemies.length; m++) {
      var e = enemies[m];
      e.prog += e.slow > 0 ? Math.floor(e.sp * 60 / 100) : e.sp;
      if (e.prog >= ROUTES[e.route].len) {
        base -= ET[e.type].leak;
        log.push([t, 'L', e.id, base]);
        if (ev) ev.leaks.push([e.id, base]);
        if (base <= 0) { fell = true; break; }
      } else { setPos(e); keep.push(e); }
    }
    if (fell) {
      fallTick = t; log.push([t, 'F', curWave, 0]);
      if (rec) { rec.fallTick = t; pushFrame(t, frameExtra, true); }
      break;
    }
    enemies = keep;
    // age & heal
    for (var a2 = 0; a2 < enemies.length; a2++) {
      var en = enemies[a2]; en.age++;
      if (en.type === 'mender' && en.age % 20 === 0) {
        if (ev) ev.heals.push([en.x, en.y]);
        for (var h = 0; h < enemies.length; h++) {
          var o = enemies[h], dx = o.x - en.x, dy = o.y - en.y;
          if (dx * dx + dy * dy <= 22500) o.hp = Math.min(o.mhp, o.hp + Math.floor(o.mhp * 8 / 100));
        }
      }
    }
    // fire
    for (var s = 0; s < 16; s++) {
      var T = turrets[s]; if (!T) continue;
      if (T.cd > 0) T.cd--;
      if (T.cd > 0) continue;
      var def = TT[T.type], px = SX[s][0] * 100 + 50, py = SX[s][1] * 100 + 50, rr = T.rng * T.rng;
      var cands = [];
      for (var c = 0; c < enemies.length; c++) {
        var ce = enemies[c];
        if (ce.hp <= 0) continue;
        if (ce.air ? !def.a : !def.g) continue;
        var ddx = ce.x - px, ddy = ce.y - py;
        if (ddx * ddx + ddy * ddy <= rr) cands.push(ce);
      }
      if (!cands.length) continue;
      var tg = null;
      if (typeof strat.target === 'function') {
        var tid = strat.target({ slot: s, type: T.type, tier: T.tier, x: px, y: py, range: T.rng }, cands.map(view));
        for (var c2 = 0; c2 < cands.length; c2++) if (cands[c2].id === tid) { tg = cands[c2]; break; }
      }
      if (!tg) {
        var best = 1e9;
        for (var c3 = 0; c3 < cands.length; c3++) { var rem = ROUTES[cands[c3].route].len - cands[c3].prog; if (rem < best) { best = rem; tg = cands[c3]; } }
      }
      var hitList = [tg];
      if (def.spl > 0) {
        hitList = [];
        var sr = def.spl * def.spl;
        for (var c4 = 0; c4 < enemies.length; c4++) {
          var oe = enemies[c4];
          if (oe.hp <= 0) continue;
          if (oe.air ? !def.a : !def.g) continue;
          var sdx = oe.x - tg.x, sdy = oe.y - tg.y;
          if (sdx * sdx + sdy * sdy <= sr) hitList.push(oe);
        }
      }
      for (var hh = 0; hh < hitList.length; hh++) {
        var he = hitList[hh];
        he.hp -= def.pierce ? T.dmg : Math.max(1, T.dmg - he.arm);
        if (def.slow > 0) he.slow = def.slow;
      }
      T.cd = def.per;
      if (ev) ev.shots.push([s, TNAMES.indexOf(T.type), tg.id, tg.x, tg.y, tg.air]);
      removeDead(t, s);
    }
    for (var z = 0; z < enemies.length; z++) if (enemies[z].slow > 0) enemies[z].slow--;
    if (rec) pushFrame(t, frameExtra, false);
  }
  function pushFrame(t, fe, fall) {
    var F = { t: t, gold: gold, base: base, wave: curWave,
      en: enemies.map(function (e) { return [e.id, ENAMES.indexOf(e.type), e.x, e.y, e.hp, e.mhp, e.slow > 0 ? 1 : 0, e.dir]; }),
      tu: turrets.map(function (T) { return T ? [TNAMES.indexOf(T.type), T.tier] : null; }),
      ev: ev, next: fe ? fe.next : null };
    rec.frames.push(F);
  }
  var h = 0x811c9dc5, js = JSON.stringify(log);
  for (var ci = 0; ci < js.length; ci++) { h ^= js.charCodeAt(ci); h = Math.imul(h, 0x01000193); }
  var hash = ('00000000' + (h >>> 0).toString(16)).slice(-8);
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: hash };
}
