      for (k = 0; k < len * 100; k += 20) out.push([p[0] * 100 + 50 + sx * k, p[1] * 100 + 50 + sy * k]);
    }
    out.push([pts[pts.length - 1][0] * 100 + 50, pts[pts.length - 1][1] * 100 + 50]);
    return out;
  }
  var RT = [mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), mkRoute([[0,6],[21,6],[21,11],[23,11]])];
  var covCache = {};
  function cov(slot, range, air) {
    var key = slot * 10000 + range * 2 + air;
    if (covCache[key] !== undefined) return covCache[key];
    var R = RT[air], n = R.length, sum = 0, tot = 0, px = SX[slot][0] * 100 + 50, py = SX[slot][1] * 100 + 50, rr = range * range;
    for (var i = 0; i < n; i++) {
      var wgt = 1 + P.endW * i / n; tot += wgt;
      var dx = R[i][0] - px, dy = R[i][1] - py;
      if (dx * dx + dy * dy <= rr) sum += wgt;
    }
    return (covCache[key] = sum / tot * (air ? 1 : 1));
  }
  var M = [0, 1000];
  function mw(w) { while (M.length <= w) M.push(Math.floor(M[M.length - 1] * 108 / 100)); return M[w]; }
  function arm(type, w) { return type === 'grunt' ? Math.floor(w / 4) : type === 'brute' ? 6 + w : 0; }
  var prevNext = null;

  function dmgAt(type, tier) { var d = TT[type].dmg; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }

  function poolValue(type, tier, slot, L, totHp) {
    var t = TT[type], d = dmgAt(type, tier), r = t.rng + 30 * (tier - 1), v = 0, i;
    var cg = t.g ? cov(slot, r, 0) : 0, ca = t.a ? cov(slot, r, 1) : 0;
    for (i = 0; i < L.length; i++) {
      var e = L[i];
      var c = e.air ? ca : cg;
      if (c === 0) continue;
      var dd = t.pierce ? d : Math.max(1, d - e.arm);
      v += e.hp * c * dd / t.per;
    }
    v = v / totHp;
    if (t.spl) v *= 1 + P.spl;
    return v;
  }

  return {
    plan: function (state) {
      var w = state.wave, i, L = [], tot = 0;
      for (i = 0; i < state.enemies.length; i++) { var en = state.enemies[i]; L.push({ hp: en.hp, arm: en.armor, air: en.air }); }
      var cur = prevNext || ['grunt', 'grunt', 'grunt', 'grunt'];
      for (i = 0; i < cur.length; i++) L.push({ hp: Math.floor(HP[cur[i]] * mw(w) / 1000), arm: arm(cur[i], w), air: cur[i] === 'wisp' ? 1 : 0 });
      for (i = 0; i < state.nextWave.length; i++) { var ty = state.nextWave[i]; L.push({ hp: Math.floor(HP[ty] * mw(w + 1) / 1000), arm: arm(ty, w + 1), air: ty === 'wisp' ? 1 : 0 }); }
      prevNext = state.nextWave;
      for (i = 0; i < L.length; i++) tot += L[i].hp;
      var airHp = 0; for (i = 0; i < L.length; i++) if (L[i].air) airHp += L[i].hp;
      var airShare = airHp / tot;
      var slots = state.slots.map(function (s) { return s.turret ? { type: s.turret.type, tier: s.turret.tier } : null; });
      var gold = state.gold, acts = [];
      var types = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
      for (var iter = 0; iter < 32; iter++) {
        var bestScore = 0, bestAct = null, bestCost = 0, s, k;
        var nFrost = 0, others = 0, anyAir = 0;
        for (s = 0; s < 16; s++) if (slots[s]) {
          if (slots[s].type === 'frost') nFrost++;
