          if (TT[slots[s].type].a) anyAir++;
        }
        for (s = 0; s < 16; s++) {
          var cs = slots[s];
          if (!cs) {
            for (k = 0; k < 5; k++) {
              var ty2 = types[k], c = TT[ty2].cost;
              if (c > gold) continue;
              if (ty2 === 'frost' && nFrost >= P.maxFrost) continue;
              var val = ty2 === 'frost' ? P.fr * cov(s, TT.frost.rng, 0) * (0.02 + others) : poolValue(ty2, 1, s, L, tot);
              var sc = val / c * BIAS[ty2];
              if (!anyAir && airShare > 0 && TT[ty2].a && ty2 !== 'frost') sc *= P.airMin;
              if (sc > bestScore) { bestScore = sc; bestAct = { op: 'build', slot: s, type: ty2 }; bestCost = c; }
            }
          } else if (cs.tier < 3) {
            var c2 = TT[cs.type].cost * (cs.tier === 1 ? 1 : 2);
            if (c2 > gold) continue;
            var v0, v1;
            if (cs.type === 'frost') { v0 = cov(s, 240 + 30 * (cs.tier - 1), 0); v1 = cov(s, 240 + 30 * cs.tier, 0); v0 *= P.fr * (0.02 + others); v1 *= P.fr * (0.02 + others); }
            else { v0 = poolValue(cs.type, cs.tier, s, L, tot); v1 = poolValue(cs.type, cs.tier + 1, s, L, tot); }
            var sc2 = (v1 - v0) / c2 * BIAS[cs.type] * P.upB;
            if (sc2 > bestScore) { bestScore = sc2; bestAct = { op: 'upgrade', slot: s }; bestCost = c2; }
          }
        }
        if (!bestAct) break;
        acts.push(bestAct); gold -= bestCost;
        if (bestAct.op === 'build') slots[bestAct.slot] = { type: bestAct.type, tier: 1 };
        else slots[bestAct.slot].tier++;
      }
      return acts;
    }
  };
}

